scwin.mapchart2_onbeforemapchange = function(info) {
    if (info.newMapCode.length >= 2) {
        //return false; // 지도 확장기능 사용하지 않음 
    }
}
scwin.mapchart2_csvHandler = function(svg, data, projection) {
    for (var i = 0; i < data.length; i++) {
        var municipality = d3.select("#" + this.id + "_map").select(".municipality.c" + data[i].code);
        municipality.style("fill", scwin.colorScale2(data[i].value));
    }
}
scwin.mapchart3_onbeforemapchange = function(info) {
    if (info.newMapCode.length >= 2) {
        return false; // 지도 확장기능 사용하지 않음 
    }
}
scwin.mapchart3_csvHandler = function(svg, data, projection) {
    for (var i = 0; i < data.length; i++) {
        var municipality = d3.select("#" + this.id + "_map").select(".municipality.c" + data[i].code);
        municipality.style("fill", scwin.colorScale3(data[i].value));
    }
}
scwin.setTooltip = function(str1, str2) {
    return "test";
}
scwin.checkStyles = function() {
    var count = 0;
    WebSquare.wUnit.getJq("path.municipality").each(function() {
        if (WebSquare.wUnit.getJq(this).attr("style").indexOf("fill: url") == -1) {
            count++;
        }
    });
    return !count;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();

    WebSquare.wUnit.addCommand("pause", "1000");

    WebSquare.wUnit.addCommand("assert", "scwin.checkStyles()", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

